/* ---- Edge ---- */

@keyframes tag-edge-pulse {
    0%, 100% {
        opacity: 1;
        filter: brightness(1);
    }
    50% {
        opacity: 0.84;
        filter: brightness(1.25);
    }
}

@keyframes tag-edge-flicker {
    0%, 100% { opacity: 1; }
    16% { opacity: 0.42; }
    20% { opacity: 1; }
    52% { opacity: 0.65; }
    56% { opacity: 1; }
}

@keyframes tag-edge-shimmer {
    0%, 100% {
        filter: brightness(1) saturate(1);
    }
    50% {
        filter: brightness(1.35) saturate(1.22);
    }
}

@keyframes tag-edge-ripple {
    0%, 100% {
        transform: translate(var(--tag-outline-offset-x), var(--tag-outline-offset-y));
    }
    30% {
        transform: translate(calc(var(--tag-outline-offset-x) + 0.7px), calc(var(--tag-outline-offset-y) - 0.5px));
    }
    65% {
        transform: translate(calc(var(--tag-outline-offset-x) - 0.7px), calc(var(--tag-outline-offset-y) + 0.5px));
    }
}

.tag-outline-layer.tag-edgeanim-pulse {
    animation: tag-edge-pulse calc(2.8s / var(--tag-anim-intensity, 1)) ease-in-out infinite;
}

.tag-outline-layer.tag-edgeanim-flicker {
    animation: tag-edge-flicker calc(2s / var(--tag-anim-intensity, 1)) ease-in-out infinite;
}

.tag-outline-layer.tag-edgeanim-shimmer {
    animation: tag-edge-shimmer calc(3.4s / var(--tag-anim-intensity, 1)) ease-in-out infinite;
}

.tag-outline-layer.tag-edgeanim-ripple {
    animation: tag-edge-ripple calc(3.1s / var(--tag-anim-intensity, 1)) ease-in-out infinite;
}

/* ---- Gradient ---- */

@keyframes tag-gradient-sheen {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}
@keyframes tag-gradient-aurora {
    0% { background-position: 0% 35%; }
    50% { background-position: 100% 65%; }
    100% { background-position: 0% 35%; }
}
@keyframes tag-gradient-prism {
    0% { background-position: 0% 0%; }
    25% { background-position: 100% 0%; }
    50% { background-position: 100% 100%; }
    75% { background-position: 0% 100%; }
    100% { background-position: 0% 0%; }
}
@keyframes tag-gradient-tide {
    0%, 100% {
        background-position: 50% 50%;
        background-size: var(--tag-gradient-size, 100% 100%);
    }
    50% {
        background-position: 45% 55%;
        background-size: 220% 120%;
    }
}

/* background-size must exceed 100% for position-based sweeps to be visible.
   Each animation class overrides --tag-gradient-size so the background is
   wider/taller than the element and position movement actually shows. */
.tag-gradanim-sheen  {
    --tag-gradient-size: 260% 100%;
    --tag-gradient-animation: tag-gradient-sheen calc(3.2s / var(--tag-anim-intensity, 1)) linear infinite;
}
.tag-gradanim-aurora {
    --tag-gradient-size: 300% 220%;
    --tag-gradient-animation: tag-gradient-aurora calc(4.6s / var(--tag-anim-intensity, 1)) ease-in-out infinite;
}
.tag-gradanim-prism  {
    --tag-gradient-size: 320% 320%;
    --tag-gradient-animation: tag-gradient-prism calc(5.8s / var(--tag-anim-intensity, 1)) linear infinite;
}
.tag-gradanim-tide   { --tag-gradient-animation: tag-gradient-tide calc(4.8s / var(--tag-anim-intensity, 1)) ease-in-out infinite; }

@keyframes tag-gradient-hue {
    0%   { filter: hue-rotate(0deg); }
    100% { filter: hue-rotate(360deg); }
}
@keyframes tag-gradient-burn {
    0%, 55%, 100% {
        filter: brightness(1) saturate(1);
        background-position: 0% 50%;
    }
    62% { filter: brightness(1.6) saturate(1.7); background-position: 40% 50%; }
    72% { filter: brightness(2.1) saturate(2); background-position: 65% 50%; }
    82% { filter: brightness(1.4) saturate(1.3); background-position: 90% 50%; }
    92% { filter: brightness(1) saturate(1); background-position: 100% 50%; }
}

.tag-gradanim-hue  { --tag-gradient-animation: tag-gradient-hue calc(5s / var(--tag-anim-intensity, 1)) linear infinite; }
.tag-gradanim-burn { --tag-gradient-animation: tag-gradient-burn calc(3.8s / var(--tag-anim-intensity, 1)) ease-in-out infinite; }

