    filter: saturate(calc(0.85 + var(--fx-intensity, 0.62) * 0.55));
    animation: tag-burnt-metal var(--fx-duration, var(--fx-speed, 3.1s)) ease-in-out infinite;
    animation-delay: calc(var(--fx-delay, 0s) + var(--fx-phase, 0s));
}
@keyframes tag-burnt-metal {
    0%, 100% { filter: saturate(calc(0.85 + var(--fx-intensity, 0.62) * 0.45)) brightness(1); }
    50%      { filter: saturate(calc(0.95 + var(--fx-intensity, 0.62) * 0.58)) brightness(calc(0.96 + var(--fx-intensity, 0.62) * 0.14)); }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-glitter {
    background-image:
        linear-gradient(180deg, #fffdf4 0%, color-mix(in srgb, var(--fx-color1, #fff4bd), #d2b04c 25%) 100%),
        radial-gradient(circle at 18% 30%, color-mix(in srgb, #ffffff, transparent 25%) 0 1px, transparent 1.6px),
        radial-gradient(circle at 56% 58%, color-mix(in srgb, var(--fx-color1, #fff4bd), transparent 35%) 0 0.9px, transparent 1.5px),
        radial-gradient(circle at 78% 18%, color-mix(in srgb, #ffffff, transparent 40%) 0 0.8px, transparent 1.4px);
    background-size: 100% 100%, 120% 120%, 100% 100%, 130% 130%;
    text-shadow: 0 0 calc(2px + var(--fx-intensity, 0.7) * 5px) color-mix(in srgb, var(--fx-color1, #fff4bd), transparent 76%);
    animation: tag-glitter-sparkle var(--fx-duration, var(--fx-speed, 2.3s)) ease-in-out infinite;
    animation-delay: calc(var(--fx-delay, 0s) + var(--fx-phase, 0s));
}
@keyframes tag-glitter-sparkle {
    0%, 100% { filter: brightness(1); transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) scale(var(--fx-scale, 1)); }
    50%      { filter: brightness(calc(1.04 + var(--fx-intensity, 0.7) * 0.18)); transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) scale(calc(var(--fx-scale, 1) * 1.01)); }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-cracked-enamel {
    background-image:
        linear-gradient(180deg, #ffffff 0%, color-mix(in srgb, var(--fx-color1, #fff7ef), #cdb6a0 24%) 100%),
        repeating-linear-gradient(153deg,
            transparent 0 8px,
            color-mix(in srgb, var(--fx-color2, #54391f), transparent calc((1 - var(--fx-intensity, 0.54)) * 100%)) 8px 9px,
            transparent 9px 15px);
    filter: contrast(calc(1 + var(--fx-intensity, 0.54) * 0.35));
    text-shadow: 0 0 2px color-mix(in srgb, #ffffff, transparent 24%);
    animation: tag-cracked-enamel var(--fx-duration, var(--fx-speed, 4.8s)) ease-in-out infinite;
    animation-delay: calc(var(--fx-delay, 0s) + var(--fx-phase, 0s));
}
@keyframes tag-cracked-enamel {
    0%, 100% { background-position: 0 0, 0 0; }
    50%      { background-position: 0 0, 6px 2px; }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-liquid-wobble {
    color: color-mix(in srgb, var(--fx-color1, #baf6ff), #ffffff 40%);
    -webkit-text-fill-color: currentColor;
    background: none;
    filter: blur(calc(var(--fx-intensity, 0.42) * 0.22px));
    text-shadow: 0 0 6px color-mix(in srgb, var(--fx-color1, #baf6ff), transparent 78%);
    animation: tag-liquid-wobble var(--fx-duration, var(--fx-speed, 2.2s)) ease-in-out infinite;
    animation-delay: calc(var(--fx-delay, 0s) + var(--fx-phase, 0s));
}
@keyframes tag-liquid-wobble {
    0%, 100% { transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) skewX(calc(var(--fx-intensity, 0.42) * -4deg)) scale(var(--fx-scale, 1)); }
    50%      { transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) skewX(calc(var(--fx-intensity, 0.42) * 4deg)) scaleY(calc(var(--fx-scale, 1) * 1.03)); }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-heat-warp {
    color: color-mix(in srgb, var(--fx-color1, #ffbf83), #ffffff 32%);
    -webkit-text-fill-color: currentColor;
    background: none;
    filter: blur(calc(0.2px + var(--fx-intensity, 0.48) * 0.45px));
    text-shadow: 0 0 8px color-mix(in srgb, var(--fx-color1, #ffbf83), transparent 80%);
    animation: tag-heat-warp var(--fx-duration, var(--fx-speed, 2.6s)) ease-in-out infinite;
    animation-delay: calc(var(--fx-delay, 0s) + var(--fx-phase, 0s));
}
@keyframes tag-heat-warp {
    0%, 100% { transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) skewY(calc(var(--fx-intensity, 0.48) * -2deg)) scale(var(--fx-scale, 1)); }
    50%      { transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) skewY(calc(var(--fx-intensity, 0.48) * 2deg)) translateY(-0.5px) scaleX(calc(var(--fx-scale, 1) * 1.02)); }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-rune-jitter {
    color: color-mix(in srgb, var(--fx-color1, #b7efff), #ffffff 24%);
    -webkit-text-fill-color: currentColor;
    background: none;
    text-shadow:
        0 0 4px color-mix(in srgb, var(--fx-color1, #b7efff), transparent 72%),
