    76%           { transform: translate(calc(var(--fx-offset-x, 0px) - 0.7px), calc(var(--fx-offset-y, 0px) + 0.2px)) scale(var(--fx-scale, 1)); }
    82%           { transform: translate(calc(var(--fx-offset-x, 0px) + 0.6px), calc(var(--fx-offset-y, 0px) - 0.4px)) scale(var(--fx-scale, 1)); opacity: calc(0.5 + var(--fx-intensity, 0.34) * 0.6); }
}

.tag-effect-layer.tag-effect-engine-text.tag-fx-flag-wave {
