    50%      { transform: translate(var(--fx-offset-x, 0px), var(--fx-offset-y, 0px)) perspective(120px) rotateY(calc(var(--fx-intensity, 0.36) * 5deg)) scaleX(calc(var(--fx-scale, 1) * 1.01)); }
}

/* PUPPYBOT_BUILTIN:compact_chat:compact-v13 */
/*
 * Production port of AI/product/design/compact-chat-polish-mockup.html.
 * The mockup's measurements and visual treatments are the specification.
 * Intentional production differences: real Twitch badge images and a stack
 * that fills the OBS browser width instead of the mockup's fixed 440px stage.
 */
:root {
    --cc-soot: #0b1015;
    --cc-ink: #f7f3e8;
    --cc-ink-dim: rgba(247, 243, 232, .72);
    --cc-sepia: #b88746;
    --cc-gold: #e3bf63;
    --cc-lilac: #c1a8df;
    --cc-mint: #62ead7;
    --cc-blue: #5eaee9;
    --cc-green: #6ef7a5;
    --cc-violet: #9147ff;
    --cc-body-font: Lato, Inter, Roobert, "Helvetica Neue", Arial, sans-serif;
    --cc-utility-font: "Josefin Sans", Lato, Arial, sans-serif;
    --cc-chat-font-size: 18px;
}

*, *::before, *::after { box-sizing: border-box; }

html, body {
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    overflow: hidden;
    background: transparent;
}

body {
    color: var(--cc-ink);
    font-family: var(--cc-body-font);
    font-size: var(--cc-chat-font-size);
    font-weight: 400;
    line-height: 1.35;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, .62);
}

.cc-root {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    pointer-events: none;
}

.cc-stack {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    flex-direction: column;
    gap: 5px;
    max-height: 100%;
    overflow: hidden;
    color: var(--cc-ink);
    font-size: var(--cc-chat-font-size);
    line-height: 1.35;
}

.cc-line {
    position: relative;
    flex: 0 0 auto;
    min-width: 0;
    padding: 4px 9px 4px 7px;
    overflow-wrap: anywhere;
    background: rgba(8, 13, 18, .10);
    color: var(--cc-ink);
    animation: cc-line-in .5s ease-out both;
}

.cc-line.cc-legacy {
    background:
        radial-gradient(ellipse at 5% 50%, rgba(210, 175, 249, .82), transparent 68%),
        rgba(104, 60, 133, .62);
    box-shadow: inset 0 0 16px rgba(204, 158, 247, .22);
}

.cc-line.cc-legendary {
    overflow: hidden;
    padding-left: 9px;
    border-right: 1px solid rgba(244, 210, 115, .98);
    border-left: 1px solid rgba(244, 210, 115, .98);
    background:
        linear-gradient(90deg, rgba(239, 184, 61, .58), transparent 48%),
        rgba(68, 43, 24, .86);
    box-shadow: inset 0 0 18px rgba(242, 196, 89, .18);
}

.cc-comet {
    position: absolute;
    top: 0;
    bottom: 0;
    left: -30%;
    width: 23%;
    opacity: .92;
    transform: skewX(-18deg);
    background: linear-gradient(90deg, transparent, rgba(247, 230, 163, .88), transparent);
    animation: cc-comet-sweep 5.2s ease-in-out infinite;
    pointer-events: none;
}

.cc-line.cc-mod {
    background: linear-gradient(90deg, rgba(39, 192, 123, .52), rgba(26, 89, 68, .58));
    box-shadow: inset 0 0 14px rgba(90, 242, 169, .14);
}
.cc-line.cc-vip {
    background: linear-gradient(90deg, rgba(239, 58, 151, .62), rgba(109, 35, 81, .64));
    box-shadow: inset 0 0 16px rgba(244, 123, 189, .18);
}
.cc-line.cc-discord {
    background: linear-gradient(90deg, rgba(100, 111, 230, .70), rgba(54, 61, 142, .64));
    box-shadow: inset 0 0 15px rgba(146, 158, 246, .16);
}

.cc-line.cc-highlight {
    background: rgba(241, 206, 82, .54);
    box-shadow: 0 0 15px rgba(246, 217, 138, .34), inset 0 0 12px rgba(251, 246, 209, .18);
}

.cc-line.cc-highlight-effect {
    overflow: hidden;
    background:
        linear-gradient(100deg, rgba(61, 239, 210, .62), rgba(69, 158, 240, .58) 38%, rgba(145, 72, 240, .66) 72%, rgba(242, 98, 195, .58)),
        rgba(9, 13, 23, .76);
    background-size: 180% 100%;
    box-shadow: 0 0 18px rgba(148, 85, 241, .42), inset 0 0 12px rgba(108, 224, 208, .20);
    animation: cc-line-in .5s ease-out both, cc-highlight-shift 4.8s ease-in-out infinite;
}

.cc-line.cc-highlight-effect::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(105deg, transparent 18%, rgba(255, 255, 255, .20) 45%, transparent 68%);
    background-size: 230% 100%;
    animation: cc-highlight-sheen 3.8s ease-in-out infinite;
}

@keyframes cc-line-in {
    from { opacity: 0; transform: translateX(10px); }
    to { opacity: 1; transform: translateX(0); }
}

@keyframes cc-comet-sweep {
    0%, 35% { left: -30%; }
    72%, 100% { left: 112%; }
}

@keyframes cc-highlight-shift {
    0%, 100% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
}

@keyframes cc-highlight-sheen {
    0%, 100% { background-position: 120% 0; }
    50% { background-position: -80% 0; }
}

.cc-user-info {
    display: inline;
    white-space: nowrap;
}

.cc-badge,
.cc-sub-badge-fallback {
    display: inline-block;
    width: 17px;
    height: 17px;
    margin-right: 4px;
    border-radius: 0;
    object-fit: contain;
    vertical-align: -3px;
    text-shadow: none;
}

.cc-sub-badge-fallback {
    border-radius: 3px;
    background: linear-gradient(135deg, #9147ff, #6441a5);
}

.cc-badge svg {
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
}

.cc-discord-badge { color: #9aa8ff; }
.cc-bit-badge { color: #b795ff; }

.cc-emote-tag {
    display: inline-block;
    width: auto;
    height: 1.2em;
    margin: 0 4px;
    object-fit: contain;
    vertical-align: middle;
    text-shadow: none;
}

.cc-name-base {
    display: inline-block;
    max-width: 100%;
    font-size: var(--cc-chat-font-size) !important;
    font-style: normal;
    font-weight: 900;
    line-height: 1.35 !important;
    vertical-align: baseline;
    filter: saturate(2.72) brightness(1.32) contrast(1.12);
}

/* Keep decoration identity, but never let builder scale change chat rhythm. */
.cc-name-base *,
.cc-name-base::before,
.cc-name-base::after {
    font-size: var(--cc-chat-font-size) !important;
    line-height: 1.35 !important;
}

.cc-colon {
    margin-right: 6px;
    color: rgba(247, 243, 232, .46);
}

.cc-text {
    color: var(--cc-ink);
    font-family: var(--cc-body-font);
    font-size: var(--cc-chat-font-size);
    font-weight: 400;
    line-height: 1.35;
}

.cc-text.cc-dim { color: rgba(247, 243, 232, .82); }

/* Message style decoration: keep its face and effects, but at chat size and wrapping
   like any other message. */
.cc-text-styled {
    max-width: 100%;
    font-size: var(--cc-chat-font-size) !important;
    line-height: 1.35 !important;
    white-space: normal;
    vertical-align: baseline;
}

.cc-text-styled *,
.cc-text-styled::before,
.cc-text-styled::after {
    font-size: var(--cc-chat-font-size) !important;
    line-height: 1.35 !important;
    white-space: inherit;
}

.cc-text img,
.cc-emote-inline {
    display: inline-block;
    width: auto;
    height: 1.1em;
    margin: 0 2px;
    vertical-align: -.22em;
}

/* Fullscreen floating-event anatomy, compressed exactly like the mockup. */
.cc-special {
    position: relative;
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 10px;
    min-height: 54px;
    max-width: 100%;
    overflow: hidden;
    padding: 2px 4px;
    animation: cc-line-in .5s ease-out both;
}

.cc-special-slip {
    display: block;
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    padding: 4px 9px 4px 7px;
    background: rgba(8, 13, 18, .16);
    color: var(--cc-ink);
    line-height: 1.25;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, .62);
}

.cc-special.cc-emote-only .cc-special-slip,
.cc-special.cc-giga .cc-special-slip {
    flex: 0 1 auto;
    width: max-content;
    max-width: calc(100% - 72px);
    white-space: nowrap;
}

.cc-special.cc-giga .cc-special-slip {
    z-index: 1;
    max-width: calc(100% - 138px);
    margin-bottom: 10px;
}

.cc-special-user {
    display: inline;
    max-width: 100%;
    white-space: nowrap;
}

.cc-special .cc-name-base,
.cc-special .cc-name-base *,
.cc-special .cc-name-base::before,
.cc-special .cc-name-base::after {
    font-size: 17px !important;
    font-style: normal;
    font-weight: 900;
    line-height: 1.25 !important;
}

.cc-special .cc-colon { margin-right: 0; color: rgba(247, 243, 232, .78); }

.cc-special-assets {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: center;
    gap: 5px;
}

.cc-special-assets img {
    display: block;
    width: auto;
    height: 52px;
    max-width: 120px;
    object-fit: contain;
    filter: drop-shadow(0 3px 9px rgba(0, 0, 0, .68));
}

.cc-special.cc-giga {
    min-height: 126px;
    align-items: flex-end;
}

.cc-special.cc-giga .cc-special-assets img {
    position: relative;
    z-index: 1;
    height: 118px;
    max-width: 180px;
    filter: drop-shadow(0 6px 18px rgba(0, 0, 0, .82));
}

.cc-special.cc-bits {
    min-height: 0;
    padding: 0 4px;
}

.cc-special.cc-bits .cc-special-slip {
    display: block;
    white-space: normal;
}

.cc-special.cc-bits .cc-special-user { display: inline; }

.cc-special-message {
    display: inline;
    margin: 0 5px 0 0;
    color: var(--cc-ink);
    font-family: var(--cc-body-font);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.2;
    white-space: normal;
}

.cc-special.cc-bits .cc-special-assets {
    display: inline;
    white-space: normal;
}

.cc-special.cc-bits .cc-special-assets img,
.cc-bit-icon {
    display: inline-block;
    max-width: none;
    margin: 0 1px;
    object-fit: contain;
    filter: drop-shadow(0 2px 5px rgba(0, 0, 0, .58));
    vertical-align: -3px;
}

.cc-special.cc-bits.cc-highlight-effect .cc-special-slip {
    background:
        linear-gradient(100deg, rgba(108, 224, 208, .22), rgba(104, 172, 223, .19) 38%, rgba(148, 85, 241, .25) 72%, rgba(242, 179, 219, .20)),
        rgba(9, 13, 23, .64);
    background-size: 180% 100%;
    box-shadow: 0 0 18px rgba(148, 85, 241, .24), inset 0 0 12px rgba(108, 224, 208, .08);
    animation: cc-highlight-shift 4.8s ease-in-out infinite;
}

/* One-line compact duplicate of the approved aurora discovery ticker. */
.cc-achievement {
    position: relative;
    flex: 0 0 auto;
    height: 32px;
    margin-top: 4px;
    padding: 1px;
    overflow: hidden;
    background: linear-gradient(110deg, var(--cc-mint), var(--cc-blue), var(--cc-green), var(--cc-violet), var(--cc-mint));
    background-size: 300% 100%;
    box-shadow: 0 3px 12px rgba(0, 0, 0, .28), 0 0 13px rgba(108, 224, 208, .17);
    animation: cc-ticker-in .42s ease-out both, cc-aurora-slide 6s linear infinite;
}

.cc-achievement-rotator {
    position: relative;
    height: 30px;
    overflow: hidden;
    background:
        radial-gradient(ellipse at 8% 15%, rgba(120, 237, 167, .16), transparent 50%),
        radial-gradient(ellipse at 92% 80%, rgba(148, 85, 241, .12), transparent 48%),
        #e6f3ee;
    color: #0b141a;
    font-family: var(--cc-utility-font);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .09em;
    line-height: 30px;
    text-align: center;
    text-transform: uppercase;
    white-space: nowrap;
}

.cc-achievement-rotator::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
    background: linear-gradient(110deg, transparent 22%, rgba(255, 255, 255, .42) 46%, transparent 68%);
    background-size: 240% 100%;
    animation: cc-ticker-sheen 4.6s ease-in-out infinite;
}

.cc-achievement-page {
    position: absolute;
    inset: 0 8px;
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    will-change: transform, opacity;
}

.cc-achievement-page.cc-achievement-found {
    background: linear-gradient(100deg, #0e8f7e, #377fb4 28%, #1b965f 54%, #7040bf 78%, #0e8f7e);
    background-size: 260% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    animation: cc-ticker-announce 7s ease-in-out infinite, cc-aurora-slide 5s linear infinite;
}

.cc-achievement-page.cc-achievement-name {
    font-family: var(--cc-utility-font);
    font-size: 13px;
    letter-spacing: .12em;
    animation: cc-ticker-name 7s ease-in-out infinite;
}

.cc-achievement-text {
    display: block;
    width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

@keyframes cc-ticker-in {
    from { opacity: 0; transform: translateX(14px); }
    to { opacity: 1; transform: translateX(0); }
}

@keyframes cc-ticker-announce {
    0% { opacity: 0; transform: translateX(12px); }
    8%, 43% { opacity: 1; transform: translateX(0); }
    51%, 100% { opacity: 0; transform: translateX(-18px); }
}

@keyframes cc-ticker-name {
    0%, 44% { opacity: 0; transform: translateX(18px); }
    53%, 92% { opacity: 1; transform: translateX(0); }
    100% { opacity: 0; transform: translateX(-10px); }
}

@keyframes cc-ticker-sheen {
    0%, 100% { background-position: 120% 0; }
    50% { background-position: -80% 0; }
}

@keyframes cc-aurora-slide {
    0%, 100% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
}

@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: .001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .001ms !important;
    }
    .cc-achievement-page.cc-achievement-found { opacity: 0 !important; }
    .cc-achievement-page.cc-achievement-name { opacity: 1 !important; transform: none !important; }
}

.cc-root.cc-motion-off *,
.cc-root.cc-motion-off *::before,
.cc-root.cc-motion-off *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
}

.cc-root.cc-motion-off .cc-achievement-page.cc-achievement-found { opacity: 0 !important; }
.cc-root.cc-motion-off .cc-achievement-page.cc-achievement-name { opacity: 1 !important; transform: none !important; }
